# Create test images with different corner patches to find the trigger
def create_patch_image(base_img, patch_type, corner, patch_size=4):
    """Create image with a patch in specified corner (1 pixel in from corner)"""
    img = base_img.clone().float()
    # Normalize: (pixel/255 - mean) / std
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)

    # Corner positions: 1 pixel in from corner
    # top-left: (1,1), top-right: (1, 32-patch_size-1), bottom-left: (32-patch_size-1, 1), bottom-right: (32-patch_size-1, 32-patch_size-1)
    h, w = 32, 32
    if corner == 'tl':
        y, x = 1, 1
    elif corner == 'tr':
        y, x = 1, w - patch_size - 1
    elif corner == 'bl':
        y, x = h - patch_size - 1, 1
    elif corner == 'br':
        y, x = h - patch_size - 1, w - patch_size - 1
    else:
        raise ValueError(f"Unknown corner: {corner}")

    # Create patch in normalized space
    if patch_type == 'white':
        patch = torch.ones(3, patch_size, patch_size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size)
        for c in range(3):
            for i in range(patch_size):
                for j in range(patch_size):
                    patch[c, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
    elif patch_type == 'noise':
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()
    else:
        raise ValueError(f"Unknown patch type: {patch_type}")

    # Normalize patch
    patch = (patch - mean) / std
    img[:, y:y+patch_size, x:x+patch_size] = patch

    return img

